if (root == nullptr) {
    root = new TreeNode<int>(item);
    return;
}

if (item < root->data) {
    avlInsert(root->left, item);
} else if (item > root->data) {
    avlInsert(root->right, item);
} else {
    return; // Duplicate items not allowed
}

// Update height
root->height = 1 + std::max(bstHeight(root->left), bstHeight(root->right));

// Get balance factor
int balance = bstHeight(root->left) - bstHeight(root->right);

// Left Left Case
if (balance > 1 && item < root->left->data) {
    avlRotateRight(root);
}

// Right Right Case
if (balance < -1 && item > root->right->data) {
    avlRotateLeft(root);
}

// Left Right Case
if (balance > 1 && item > root->left->data) {
    avlRotateLeft(root->left);
    avlRotateRight(root);
}

// Right Left Case
if (balance < -1 && item < root->right->data) {
    avlRotateRight(root->right);
    avlRotateLeft(root);
}

